<template>
  <div ref="msgListRef" class="mobile-shared-msg-list" @scroll="handleScroll" :style="containerStyle">
    <div v-for="(item,index) in msgList" :key="item.id"
         :class="['mobile-message-container', { 'user-message': item.role === MSG_ROLE_USER, 'assistant-message': item.role === MSG_ROLE_ASSISTANT, 'first-message': index === 0 }]">
      <div :class="['mobile-message-content-wrapper', { 'user-content': item.role === MSG_ROLE_USER, 'assistant-content': item.role === MSG_ROLE_ASSISTANT }]">
        <mobile-msg-item-text
          :ref="el => { if(el) setItemRef(item.id, el) }"
          :content="item.content"
          :role="item.role"
          :isMarkdown="item.isMarkdown"
          :typing="false"
          :showLoading="false"
          :hasThinking="item.hasThinking"
          :thinkingProcess="item.reasoning_content"
          :thinkingStatus="item.thinking_status"
          :message-status="item.messageStatus"
          :isRetrying="false"
        >
          <template #footer>
            <div class="mobile-footer-container" :style="{justifyContent: item.role === MSG_ROLE_USER ? 'flex-end' : 'flex-start'}">
              <!-- 移动端操作栏：只有AI消息才显示，且为只读模式 -->
              <mobile-msg-action-bar
                v-if="item.messageStatus !== MESSAGE_STATUS.FAILED && !item.showLoading && item.content"
                :content="item.content"
                :messageId="item.id"
                :role="item.role"
                :showRegenerate="false"
                :showShare="false"
                :showLike="false"
                :showDislike="false"
                :showMore="false"
                @onRegenerate="() => {}"
                @onFeedback="() => {}"
                @onReportIssue="() => {}"
              />
            </div>
          </template>
        </mobile-msg-item-text>
      </div>
    </div>

    <!-- 移动端加载更多提示（底部） -->
    <div v-if="loadingType === 'more' && !isLoadingAll" class="mobile-loading-more">
      <van-loading type="spinner" size="20px" />
      <span>{{ t('loading') }}</span>
    </div>
    <div ref="lastMsgRef" class="mobile-last-msg-ref"></div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed, nextTick, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { Loading } from 'vant';
import MobileMsgItemText from '@/mobile/components/business/mobile-msg-item-text.vue';
import MobileMsgActionBar from '@/mobile/components/business/mobile-msg-action-bar.vue';
import { pxToRem } from '@/utils/px-to-rem';
import { ApiShare } from '@/api/api-share';
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, MESSAGE_STATUS, onSendParseMsg, onAIParseMsg } from '@/types/msg.ts';

const { t } = useI18n();

const props = defineProps({
  sharedId: {
    type: String,
    required: true,
  },
  isLoadingAll: {
    type: Boolean,
    default: false
  },
  paddingTop: {
    type: String,
    default: pxToRem('10px')
  }
});

const emit = defineEmits(['onLoadComplete', 'onHasMoreChange', 'onScroll']);

// 消息列表
const msgList = ref([]);
const msgListRef = ref(null);
const lastMsgRef = ref(null);

// 分页和加载状态
const pageSize = ref(50);
const hasMore = ref(false);
const isLoading = ref(false);
const loadingType = ref('none'); // 'none', 'initial', 'more'
const cursor = ref(null); // 分页游标

// 消息组件引用
const itemRefs = ref({});

// 容器样式
const containerStyle = computed(() => {
  return {
    paddingTop: props.paddingTop
  };
});

// 设置消息组件的引用
const setItemRef = (id, el) => {
  itemRefs.value[id] = el;
};

// 获取特定消息组件的引用
const getItemRef = (id) => {
  return itemRefs.value[id];
};

// 处理滚动事件 - 移动端优化的上拉加载
const handleScroll = (e) => {
  const el = e.target;
  const scrollTop = el.scrollTop;
  const scrollHeight = el.scrollHeight;
  const clientHeight = el.clientHeight;

  // 发出滚动事件给父组件
  emit('onScroll', { scrollTop, scrollHeight, clientHeight });

  // 移动端检查是否滚动到底部附近（预留150px触发加载，适应移动端触摸滚动）
  const isNearBottom = scrollHeight - scrollTop - clientHeight < 150;

  // 只有在非加载全部状态下才触发单次加载
  if (isNearBottom && !isLoading.value && hasMore.value && !props.isLoadingAll) {
    loadMoreMessages();
  }
};

// 加载消息列表
const loadMessages = async (isInitial = false, showLoading = true) => {
  // 如果是初始加载，重置状态
  if (isInitial) {
    cursor.value = null;
    msgList.value = [];
    hasMore.value = true;
  } else if (isLoading.value || !hasMore.value) {
    // 非初始加载时，如果正在加载或没有更多数据，则直接返回
    return;
  }

  // 设置加载状态
  if (showLoading) {
    isLoading.value = true;
    loadingType.value = isInitial ? 'initial' : 'more';
  }

  try {
    // 确保sharedId存在
    if (!props.sharedId) {
      isLoading.value = false;
      return;
    }

    // 从API获取分享会话数据
    const res = await ApiShare.getSharedSession(props.sharedId, pageSize.value, cursor.value || null);

    if (res.data && Array.isArray(res.data.items) && res.data.items.length > 0) {
      // 处理消息数据 - 分享页面不需要倒序
      const newMessages = res.data.items.map(item => {
        if (item.role === MSG_ROLE_USER) {
          return onSendParseMsg(item);
        } else {
          return onAIParseMsg(item, false);
        }
      });

      // 添加到现有消息列表
      if (isInitial) {
        msgList.value = newMessages;
      } else {
        msgList.value = [...msgList.value, ...newMessages];
      }

      // 更新分页状态
      const newHasMore = res.data.has_more === true;
      if (hasMore.value !== newHasMore) {
        hasMore.value = newHasMore;
        emit('onHasMoreChange', newHasMore);
      }

      // 更新cursor为最后一个消息的id
      if (res.data.items.length > 0 && hasMore.value) {
        cursor.value = res.data.items[res.data.items.length - 1].id;
      } else {
        cursor.value = null;
      }

      // 通知父组件加载完成
      emit('onLoadComplete', hasMore.value);
    } else {
      // 没有数据
      if (hasMore.value !== false) {
        hasMore.value = false;
        emit('onHasMoreChange', false);
      }
      cursor.value = null;
      if (isInitial) {
        msgList.value = [];
        emit('onLoadComplete', hasMore.value);
      }
    }
  } catch (error) {
    console.error('Failed to load shared messages:', error);
    hasMore.value = false;
    // 在错误情况下也要通知父组件
    if (isInitial) {
      emit('onLoadComplete', hasMore.value);
    }
  } finally {
    // 移动端稍长的延迟，确保加载状态稳定
    setTimeout(() => {
      isLoading.value = false;
      loadingType.value = 'none';
    }, 400);
  }
};

// 加载更多消息
const loadMoreMessages = () => loadMessages(false);

// 初始加载消息
const getMsgList = (isInitial = true, showLoading = true) => loadMessages(isInitial, showLoading);

// 加载全部消息
const loadAllMessages = async () => {
  if (isLoading.value) return;

  try {
    // 循环加载直到没有更多数据
    while (hasMore.value) {
      // 临时重置加载状态，允许API调用
      isLoading.value = false;
      await loadMessages(false, true); // 不显示loading，避免状态冲突
      // 移动端适当延长间隔，避免请求过于频繁
      await new Promise(resolve => setTimeout(resolve, 300));
    }

    // 滚动到底部
    await scrollToBottom();

  } catch (error) {
    console.error('Failed to load all messages:', error);
  } finally {
    isLoading.value = false;
  }
};

// 移动端优化的滚动到底部
const scrollToBottom = async () => {
  await nextTick();
  if (msgListRef.value) {
    // 移动端使用smooth滚动
    msgListRef.value.scrollTo({
      top: msgListRef.value.scrollHeight,
      behavior: 'smooth'
    });
  }
};

// 监听sharedId变化
watch(() => props.sharedId, (newSharedId, oldSharedId) => {
  if (newSharedId && newSharedId !== oldSharedId) {
    getMsgList(true, true);
  }
}, { immediate: true });

// 组件挂载时加载数据
onMounted(() => {
  if (props.sharedId) {
    getMsgList(true, true);
  }
});

// 对外暴露方法
defineExpose({
  getMsgList,
  getItemRef,
  msgList,
  loadAllMessages,
  scrollToBottom
});
</script>

