<template>
  <div class="share-page">
    <!-- 顶部导航栏 -->
    <div class="navbar-container">
      <mobile-app-navbar 
        :isShowLogo="true" 
        :isShowHistoryButton="false" 
        :isShowAddChatButton="true" 
        :isShowCenter='false' 
      />
    </div>
    
    <!-- 消息列表区域 -->
    <div class="message-container" v-if="shareId">
      <mobile-shared-message-list
        ref="sharedMessageListRef"
        :sharedId="shareId"
        :isLoadingAll="isLoadingAll"
        :paddingTop="windowWidth < 1200 ? '0': pxToRem('10px')"
        @onLoadComplete="handleLoadComplete"
        @onHasMoreChange="handleHasMoreChange"
        @onScroll="handleMessageListScroll"
      />
      
      <!-- 移动端加载全部按钮 -->
      <div 
        class="mobile-load-all-button" 
        :class="{ 'loading': isLoadingAll }"
        @click="clickLoadAll"
        v-if="hasMoreMessages || isLoadingAll || (allMessagesLoaded && !isAtBottom)"
      >
        <div class="button-inner">
          <van-icon name="arrow-down" size="20px" />
        </div>
        <div class="loading-border" v-if="isLoadingAll"></div>
      </div>
    </div>
    
    <!-- 继续聊天按钮 -->
    <div class="continue-chat-container">
      <mobile-l-button
        :text="isLoggedIn ? t('continueChatting') : t('signInToContinueConversation')"
        width="auto"
        height="48px"
        @onClick="clickContinueChat"
      />
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch, onUnmounted } from 'vue';
import { useRoute } from 'vue-router';
import { useUserStore } from '@/store/modules/user';
import { routerTo } from '@/router/navigation';
import { ROUTER_PATHS } from '@/router/constants';
import { useI18n } from 'vue-i18n';
import MobileLButton from '@/mobile/components/mobile-l-button.vue';
import MobileSharedMessageList from '@/mobile/components/business/mobile-shared-message-list.vue';
import MobileAppNavbar from '@/mobile/components/layout/mobile-app-navbar.vue';
import { ApiShare } from '@/api/api-share';
import pxToRem from '@/utils/px-to-rem';

// 国际化
const { t } = useI18n();

// 路由和状态管理
const route = useRoute();
const userStore = useUserStore();

// 响应式数据
const currentSessionId = ref(null);
const sharedMessageListRef = ref(null);
const isLoadingAll = ref(false);
const allMessagesLoaded = ref(false);
const hasMoreMessages = ref(true);
const isAtBottom = ref(false);

// 跟踪窗口宽度
const windowWidth = ref(window.innerWidth);

// 计算属性
const isLoggedIn = computed(() => userStore.isLoggedIn);
const shareId = computed(() => route.params.shareId);

// 监听登录状态变化
watch(isLoggedIn, (newValue) => {
  if (newValue && !currentSessionId.value) {
      initSessionChat();
  }
});

// 登录按钮点击事件
const clickLogin = () => {
  // 传递当前分享页面路径，登录成功后自动返回
  const redirectPath = route.fullPath;
  routerTo(ROUTER_PATHS.LOGIN, { redirect: redirectPath });
};

// 加载全部消息按钮点击事件
const clickLoadAll = async () => {
  if (!sharedMessageListRef.value || isLoadingAll.value) return;
  
  // 如果已经加载完所有消息，直接滚动到底部
  if (allMessagesLoaded.value) {
    await sharedMessageListRef.value.scrollToBottom();
    return;
  }
  
  isLoadingAll.value = true;
  try {
    await sharedMessageListRef.value.loadAllMessages();
    allMessagesLoaded.value = true; // 标记所有消息已加载
  } catch (error) {
    console.error('Failed to load all messages:', error);
  } finally {
    isLoadingAll.value = false;
  }
};

// 处理加载完成事件
const handleLoadComplete = (isInitial) => {
  // 如果是初始加载，重置按钮显示状态
  if (isInitial) {
      allMessagesLoaded.value = false;
      hasMoreMessages.value = true;
  }
};

// 处理是否有更多消息的状态变化
const handleHasMoreChange = (hasMore) => {
  hasMoreMessages.value = hasMore;
  if (!hasMore) {
      allMessagesLoaded.value = true;
  }
};

// 处理消息列表滚动事件
const handleMessageListScroll = (scrollData) => {
  // 当滚动到底部附近时隐藏按钮
  const { scrollTop, scrollHeight, clientHeight } = scrollData;
  const isNearBottom = scrollHeight - scrollTop - clientHeight < 130;
  isAtBottom.value = isNearBottom;
};

// 继续聊天按钮点击事件
const clickContinueChat = () => {
  // 暂时不处理
  console.log('Continue chatting clicked');
  // ElMessage.error('No Support');
};

// 监听窗口大小变化
const handleResize = () => {
  windowWidth.value = window.innerWidth;
};

const initSessionChat = async () => {
  // const res = await ApiShare.getSharedSession(shareId.value, 50, 0);
  // currentSessionId.value = res.data?.id || 0;
  // currentSessionId.value = shareId.value;
};

// 生命周期
onMounted(() => {
  initSessionChat();
  window.addEventListener('resize', handleResize);
});

onUnmounted(() => {
window.removeEventListener('resize', handleResize);
});

</script>

